function sk1020_api_csrf(): void {if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&function_exists('csrf_check'))csrf_check();}
function sk1020_api_action(): string{return substr((string)($_REQUEST['action']??''),0,60);}
