$action=sk1020_api_action();$method=$_SERVER['REQUEST_METHOD']??'GET';
if($action==='suggest'){
  $q=trim((string)($_GET['q']??''));if(mb_strlen($q)<2)sk1020_api_out(['ok'=>true,'items'=>[]]);$tid=sk1020_tenant_id();$items=[];
  foreach([['business','businesses',['name','title']],['product','store_products',['title','name']],['property','city_portal_items',['title','name']],['news','news_posts',['title_en','title']]] as [$type,$table,$names]){
    if(!sk1020_table_exists($table))continue;$cols=sk1020_columns($table);$name='';foreach($names as $n)if(in_array($n,$cols,true)){$name=$n;break;}if($name==='')continue;$w=["`$name` LIKE ?"];$p=['%'.$q.'%'];if($tid>0&&in_array('tenant_id',$cols,true)){$w[]='tenant_id=?';$p[]=$tid;}if($type==='property'&&in_array('content_type',$cols,true)){$w[]="content_type='property'";}try{$st=db()->prepare('SELECT * FROM `'.$table.'` WHERE '.implode(' AND ',$w).' ORDER BY id DESC LIMIT 4');$st->execute($p);foreach($st->fetchAll() as $r){$items[]=['type'=>$type,'id'=>(int)$r['id'],'title'=>sk1020_title($r),'image'=>sk1020_image($r),'url'=>(sk1020_entity_map($type)[1]??'#').(int)$r['id']];}}catch(Throwable $e){}
  }
  sk1020_api_out(['ok'=>true,'items'=>array_slice($items,0,10)]);
