if($action==='track'){if($type&&$id)sk1020_api_entity($type,$id);$event=substr((string)($_POST['event']??'view'),0,48);sk1020_log($event,$type,$id,['source'=>'frontend']);if(in_array($event,['view','card_click'],true)&&$type&&$id)sk1020_recent_touch($type,$id);sk1020_api_out(['ok'=>true]);}
if($action==='toggle_favorite'){sk1020_api_entity($type,$id);if(!sk1020_feature('favorites'))sk1020_api_out(['ok'=>false,'message'=>'Favorites are disabled.'],403);try{$q=$uid>0?db()->prepare('SELECT id FROM visitor_favorites_v1020 WHERE tenant_id=? AND (visitor_key=? OR user_id=?) AND entity_type=? AND entity_id=? LIMIT 1'):db()->prepare('SELECT id FROM visitor_favorites_v1020 WHERE tenant_id=? AND visitor_key=? AND entity_type=? AND entity_id=? LIMIT 1');$uid>0?$q->execute([$tid,$vk,$uid,$type,$id]):$q->execute([$tid,$vk,$type,$id]);$existing=(int)($q->fetchColumn()?:0);if($existing){if($uid>0)db()->prepare('DELETE FROM visitor_favorites_v1020 WHERE tenant_id=? AND user_id=? AND entity_type=? AND entity_id=?')->execute([$tid,$uid,$type,$id]);db()->prepare('DELETE FROM visitor_favorites_v1020 WHERE tenant_id=? AND visitor_key=? AND entity_type=? AND entity_id=?')->execute([$tid,$vk,$type,$id]);$on=false;}else{db()->prepare('INSERT INTO visitor_favorites_v1020(tenant_id,visitor_key,user_id,entity_type,entity_id) VALUES(?,?,?,?,?)')->execute([$tid,$vk,$uid,$type,$id]);$on=true;sk1020_log('favorite',$type,$id);}sk1020_api_out(['ok'=>true,'active'=>$on]);}catch(Throwable $e){sk1020_api_out(['ok'=>false,'message'=>'Could not update favorite.'],500);}}
