if($action==='subscribe_alert'){sk1020_api_entity($type,$id);$alert=substr((string)($_POST['alert_type']??'updates'),0,40);$channel=substr((string)($_POST['channel']??'in_app'),0,24);$target=mb_substr(trim((string)($_POST['target']??'')),0,255);$r=sk1020_fetch_entity($type,$id);$last=sk1020_value($r,['sale_price','price','amount'],null);try{db()->prepare('INSERT INTO growth_alerts_v1020(tenant_id,visitor_key,user_id,entity_type,entity_id,alert_type,channel,target,last_value,enabled) VALUES(?,?,?,?,?,?,?,?,?,1) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id),target=VALUES(target),enabled=1,last_value=VALUES(last_value)')->execute([$tid,$vk,$uid,$type,$id,$alert,$channel,$target,is_numeric($last)?$last:null]);sk1020_api_out(['ok'=>true,'message'=>'Alert enabled.']);}catch(Throwable $e){sk1020_api_out(['ok'=>false,'message'=>'Could not enable alert.'],500);}}
if($action==='question'){if(!sk1020_feature('community'))sk1020_api_out(['ok'=>false],403);sk1020_api_entity($type,$id);$q=mb_substr(trim((string)($_POST['question']??'')),0,1000);if(mb_strlen($q)<8)sk1020_api_out(['ok'=>false,'message'=>'Please enter a clearer question.'],422);try{db()->prepare('INSERT INTO growth_questions_v1020(tenant_id,visitor_key,user_id,entity_type,entity_id,question,status) VALUES(?,?,?,?,?,? ,\'pending\')')->execute([$tid,$vk,$uid,$type,$id,$q]);sk1020_api_out(['ok'=>true,'message'=>'Question submitted for review.']);}catch(Throwable $e){sk1020_api_out(['ok'=>false,'message'=>'Could not submit question.'],500);}}
