if($action==='claim_business'){if($type!=='business')$type='business';sk1020_api_entity($type,$id);$name=mb_substr(trim((string)($_POST['name']??'')),0,190);$phone=mb_substr(trim((string)($_POST['phone']??'')),0,60);$email=mb_substr(trim((string)($_POST['email']??'')),0,190);$note=mb_substr(trim((string)($_POST['note']??'')),0,1200);if($name==='')sk1020_api_out(['ok'=>false,'message'=>'Name is required.'],422);try{db()->prepare('INSERT INTO growth_business_claims_v1020(tenant_id,business_id,visitor_key,user_id,claimant_name,claimant_phone,claimant_email,note) VALUES(?,?,?,?,?,?,?,?)')->execute([$tid,$id,$vk,$uid,$name,$phone,$email,$note]);sk1020_api_out(['ok'=>true,'message'=>'Business claim submitted for admin review.']);}catch(Throwable $e){sk1020_api_out(['ok'=>false,'message'=>'Could not submit claim.'],500);}}
