if($action==='campaign_click'){$cid=max(0,(int)($_POST['campaign_id']??0));if($cid>0&&sk1020_table_exists('growth_campaigns_v1020'))try{db()->prepare('UPDATE growth_campaigns_v1020 SET clicks=clicks+1 WHERE tenant_id=? AND id=?')->execute([$tid,$cid]);}catch(Throwable $e){}sk1020_log('campaign_click','campaign',$cid);sk1020_api_out(['ok'=>true]);}
